#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main() {
    int n;
    scanf("%d", &n);

    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    // dp[i][j] = min flips for first i pancakes with j carried over flips to position i
    // j can be 0 or 1 because we only flip pairs (i-1,i) or (i,i+1)
    int dp[2][2];
    memset(dp, 0x3f, sizeof(dp));
    dp[0][0] = 0; // no pancakes processed, no carry

    for (int i = 0; i < n; i++) {
        int cur[2];
        memset(cur, 0x3f, sizeof(cur));
        for (int carry = 0; carry < 2; carry++) {
            if (dp[i % 2][carry] > 1000000000) continue;
            int need = a[i] - carry;
            if (need < 0) need = 0; // already satisfied
            // option 1: flip (i, i+1) if possible
            if (i < n - 1) {
                // we can decide to flip this pair 0 or 1 time
                for (int flip = 0; flip <= 1; flip++) {
                    int new_need = need - flip;
                    if (new_need < 0) continue;
                    // remaining need must be satisfied by a flip on (i-1,i) which we already accounted as carry
                    // actually carry already handled the left side, now we decide right side carry
                    int new_carry = flip;
                    int val = dp[i % 2][carry] + flip;
                    if (val < cur[new_carry]) {
                        cur[new_carry] = val;
                    }
                }
            } else {
                // last pancake, only left side possible (already handled by carry)
                if (need == 0) {
                    cur[0] = dp[i % 2][carry];
                }
            }
        }
        // also consider that we might have flipped (i-1,i) which contributed to carry
        // the carry from previous step already accounts for that.
        memcpy(dp[(i + 1) % 2], cur, sizeof(cur));
    }

    int ans = dp[n % 2][0];
    if (ans > 1000000000) ans = -1;
    printf("%d\n", ans);

    free(a);
    return 0;
}

