int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long prev = 0, x, ans = 0;

    for (int i = 0; i < n; i++) {
        scanf("%lld", &x);
        if (x > prev) ans += x - prev;
        prev = x;
    }

    printf("%lld\n", ans);
    return 0;
}

