public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            int[] r = new int[n];
            for (int i = 0; i < n; i++) r[i] = sc.nextInt();

            if (n == 1) {
                // Can't flip a single pancake (need 2 adjacent), unless r[0]==0
                if (r[0] == 0) System.out.println(0);
                else System.out.println(-1);
                continue;
            }

            long[] x = new long[n - 1];
            x[0] = r[0];
            boolean possible = true;
            for (int i = 1; i < n - 1; i++) {
                x[i] = r[i] - x[i-1];
                if (x[i] < 0) { possible = false; break; }
            }
            if (possible) {
                // Check last pancake
                long last = x[n-2];
                if (last != r[n-1]) possible = false;
            }

            if (!possible) {
                System.out.println(-1);
            } else {
                long total = 0;
                for (long xi : x) total += xi;
                System.out.println(2 * total);
            }
        }
    }
}

