using namespace std;
int main(){
    int n; cin>>n;
    vector<long long> r(n);
    for(auto &x:r) cin>>x;
    long long best = LLONG_MAX;
    // Try y1 from 0 to some max
    for(long long y1=0; y1<=2e6; y1++){
        vector<long long> x(n-1);
        x[0]=r[0]-y1;
        bool ok=true;
        if(x[0]<0){ok=false;}
        for(int i=1;i<n-1&&ok;i++){
            x[i]=r[i]-x[i-1];
            if(x[i]<0) ok=false;
        }
        if(!ok) continue;
        long long yn=r[n-1]-x[n-2];
        if(yn<0) continue;
        long long tot=y1+yn;
        for(auto v:x) tot+=2*v;
        best=min(best,tot);
    }
    cout<<best<<endl;
}

